package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strings"
)
​
// Trie 节点定义
type TrieNode struct {
    isWord   bool
    // 26字母 + 空格
    children [27]*TrieNode
}
​
// 插入词
func insertWord(root *TrieNode, word string) {
    node := root
    for _, c := range word {
        index := 26
        if c != ' ' {
            index = int(c - 'a')
        }
        if node.children[index] == nil {
            node.children[index] = &TrieNode{}
        }
        node = node.children[index]
    }
    node.isWord = true
}
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
    root := &TrieNode{}
​
    // 读取词典
    for scanner.Scan() {
        line := scanner.Text()
        if line == "" {
            break
        }
        insertWord(root, line)
    }
​
    // 读取长字符串
    scanner.Scan()
    sentence := scanner.Text()
    inputWords := strings.Split(sentence, " ")
    n := len(inputWords)
    index := 0
    // 记录每次token的起始和终止位置
    var result [][2]int
​
    for index < n {
        node := root
        tmpIndex := index
        // 记录合法匹配的位置
        lastValidIndex := -1
​
        for {
            if tmpIndex >= n {
                break
            }
            word := inputWords[tmpIndex]
            flag := true
            for _, ch := range word {
                pos := int(ch - 'a')
                // 不存在
                if node.children[pos] == nil {
                    flag = false
                    break
                }
                node = node.children[pos]
            }
            if !flag {
                break
            }
            // 更新合法位置
            if node.isWord {
                lastValidIndex = tmpIndex
            }
            // 空格判断
            node = node.children[26]
            if node == nil {
                break
            }
            tmpIndex++
        }
​
        if lastValidIndex != -1 {
            result = append(result, [2]int{index, lastValidIndex})
            index = lastValidIndex + 1
        } else {
            result = append(result, [2]int{index, index})
            index++
        }
    }
​
    // 输出
    for _, p := range result {
        start, end := p[0], p[1]
        fmt.Print("(")
        fmt.Print(strings.Join(inputWords[start:end+1], " "))
        fmt.Print(")")
    }
}
